   177	const TEXT_STYLE_TO_CLASS: ReadonlyArray<readonly [keyof typeof textStyles, string]> = [
   178	  ['heading1Strong', '.zimm-text-h1-strong'],
   179	  ['heading1', '.zimm-text-h1'],
   180	  ['heading2', '.zimm-text-h2-strong'],
   181	  ['heading3', '.zimm-text-h3-strong'],
