import React from 'react';
import { describe, expect, test } from 'vitest';
import { render } from '@testing-library/react';
import {
  chakra,
  ChakraProvider,
  extendTheme,
  useMultiStyleConfig,
  useStyleConfig,
} from '@chakra-ui/react';
import baseTheme from './index';
import { textStyles } from './foundation/typography';

const ProbeParts = {
  parts: ['declared'],
  baseStyle: { declared: { color: 'red' }, undeclared: { color: 'blue' } },
  variants: { v: { declared: { margin: '1px' }, undeclared: { margin: '2px' } } },
};
const ProbeExplicit = { baseStyle: { fontSize: '2rem', fontWeight: 900 } };
const ProbeComposite = { baseStyle: { textStyle: 'heading3' } };

const theme = extendTheme(
  { components: { ProbeParts, ProbeExplicit, ProbeComposite } },
  baseTheme,
);

let captured: Record<string, unknown> = {};
const MultiHarness = ({ variant }: { variant?: string }) => {
  const s = useMultiStyleConfig('ProbeParts', variant ? { variant } : {});
  captured[variant ? 'withVariant' : 'baseOnly'] = s;
  return null;
};
const SingleHarness = ({ recipe, ts }: { recipe: string; ts?: string }) => {
  const styles = useStyleConfig(recipe, {});
  return <chakra.p data-testid="el" __css={styles} textStyle={ts} />;
};

describe('PROBE', () => {
  test('A: does parts gate baseStyle?', () => {
    render(
      <ChakraProvider theme={theme}>
        <MultiHarness />
        <MultiHarness variant="v" />
      </ChakraProvider>,
    );
    console.log('baseStyle only    ->', JSON.stringify(captured.baseOnly));
    console.log('baseStyle+variant ->', JSON.stringify(captured.withVariant));
  });

  test('B1: recipe explicit font props vs JSX textStyle', () => {
    const { getByTestId } = render(
      <ChakraProvider theme={theme}>
        <SingleHarness recipe="ProbeExplicit" ts="caption" />
      </ChakraProvider>,
    );
    const cs = window.getComputedStyle(getByTestId('el'));
    console.log('caption is', JSON.stringify(textStyles.caption));
    console.log('B1 RESULT fontSize=', cs.fontSize, 'fontWeight=', cs.fontWeight);
  });

  test('B2: recipe composite textStyle vs JSX textStyle', () => {
    const { getByTestId } = render(
      <ChakraProvider theme={theme}>
        <SingleHarness recipe="ProbeComposite" ts="caption" />
      </ChakraProvider>,
    );
    const cs = window.getComputedStyle(getByTestId('el'));
    console.log('heading3 is', JSON.stringify(textStyles.heading3));
    console.log('B2 RESULT fontSize=', cs.fontSize, 'fontWeight=', cs.fontWeight);
  });
});
EOF
